"""Consolidate pinned retained daily files; no prices or labels are decoded."""
from pathlib import Path
import datetime,hashlib,json,os
from execute_kalshi import O,R,C,onboard
def main():
 audit=json.loads((O/"source-manifests.json").read_text())
 records=[];mapping={}
 for source in ["binance-btcusdt-1m","binance-btcbvol","binance-ethusdt-1m","binance-ethbvol"]:
  files={}
  for m in sorted([m for m in audit["manifests"] if m["source"]==source],key=lambda m:m["acquired_at"]):
   for f in m["files"]:
    rel=f["relpath"]
    if rel.startswith("files/") and rel.endswith(".parquet") and "2023-06-20"<=Path(rel).stem<"2026-10-12":files[Path(rel).name]=(m,f)
  stage=O/"bounded-tapes"/source;stage.mkdir(parents=True,exist_ok=True)
  for filename,(m,f) in files.items():
   src=Path(m["path"]).parent/"payload"/f["relpath"]
   assert hashlib.sha256(src.read_bytes()).hexdigest()==f["sha256"]
   dest=stage/filename
   if not dest.exists():os.link(src,dest)
   assert hashlib.sha256(dest.read_bytes()).hexdigest()==f["sha256"]
   records.append(dict(source=source,filename=filename,origin=str(src),sha256=f["sha256"],manifest_sha256=m["manifest_sha256"]))
  name="retained-history-"+source+"-20261019";mapping[source]=name
  cfg=dict(path=str(stage),as_of="2026-10-19T00:00:00Z",stream="files",include=["*.parquet"],notes="Latest pinned retained version per day over original full feature warmup; day filenames strictly beforeOct12. Consolidation fixes latest incremental-snapshot-only reader, no values modified.")
  cfgname="source-retained-"+source+".json";(C/cfgname).write_text(json.dumps(cfg,indent=2)+"\n")
  onboard(name,"localblobs",cfgname,"files")
 amendments=json.loads((O/"technical-amendments.json").read_text())
 for name in ["run-retained-panel.json","run-retained-oct08-12-features.json"]:
  p=C/name;before=hashlib.sha256(p.read_bytes()).hexdigest();doc=json.loads(p.read_text())
  def update(x):
   if isinstance(x,dict):
    for k,v in x.items():
     if k=="source" and isinstance(v,str) and v in mapping:x[k]=mapping[v]
     else:update(v)
   elif isinstance(x,list):
    for v in x:update(v)
  update(doc);p.write_text(json.dumps(doc,indent=2)+"\n")
  amendments.append(dict(time=datetime.datetime.now(datetime.timezone.utc).isoformat(),kind="technical_snapshot_consolidation",config=name,before_sha256=before,after_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),reason="Current latest Binance snapshots contain Oct18 only; generic reader does not union snapshots. Consolidate already-inventoried daily files within original bounds, preserve features/model/evaluation rules."))
 (O/"technical-amendments.json").write_text(json.dumps(amendments,indent=2)+"\n")
 (O/"bounded-tape-provenance.json").write_text(json.dumps(records,indent=2)+"\n")
 print("Consolidated",len(records),"hash-verified pre-Oct12 daily files",flush=True)
if __name__=="__main__":main()

